recipes.code:
{
  "inputs": [
    {
      "id": "bidsparq-api-key",
      "type": "promptString",
      "description": "Your bsq_live_... API key from https://bidsparq.com/settings/api-keys",
      "password": true
    }
  ],
  "servers": {
    "mcp": {
      "type": "stdio",
      "command": "npx",
      "args": [
        "-y",
        "bidsparq-mcp-server@0.1.7"
      ],
      "env": {
        "BIDSPARQ_API_KEY": "${input:bidsparq-api-key}",
        "BIDSPARQ_BASE_URL": "<bidsparq-base-url>"
      }
    }
  }
}
